{
  "decisions": [
    {
      "decision": "variable_domain",
      "evidence": "\"each full-time employee must work five consecutive days\" and \"minimize the number of full-time employees who must be hired\"",
      "options": [
        "NonNegativeIntegers",
        "NonNegativeReals",
        "Binary"
      ],
      "plausibility": [
        0.6,
        0.35,
        0.05
      ],
      "majority_option": "NonNegativeIntegers"
    },
    {
      "decision": "coverage_constraint_direction",
      "evidence": "\"The post office wants to meet its daily requirements\"",
      "options": [
        ">= requirement (at least the required number)",
        "= requirement (exactly the required number)",
        "<= requirement (at most the required number)"
      ],
      "plausibility": [
        0.9,
        0.08,
        0.02
      ],
      "majority_option": ">= requirement (at least the required number)"
    },
    {
      "decision": "shift_pattern_orientation",
      "evidence": "\"each full-time employee must work five consecutive days and then receive two days off. For example, an employee who works Monday to Friday must be off on Saturday and Sunday.\"",
      "options": [
        "x[s] = employees whose 5-day block starts on day s (covers s, s+1, ..., s+4)",
        "x[s] = employees whose 2-day off block starts on day s (covers all days except s, s+1)"
      ],
      "plausibility": [
        0.85,
        0.15
      ],
      "majority_option": "x[s] = employees whose 5-day block starts on day s (covers s, s+1, ..., s+4)"
    },
    {
      "decision": "objective_quantity",
      "evidence": "\"minimize the number of full-time employees who must be hired\"",
      "options": [
        "minimize total employees hired = sum of all shift-start variables",
        "minimize total employee-days worked = 5 * sum of all shift-start variables"
      ],
      "plausibility": [
        0.95,
        0.05
      ],
      "majority_option": "minimize total employees hired = sum of all shift-start variables"
    },
    {
      "decision": "day_index_orientation",
      "evidence": "\"Monday requires 17 employees,Tuesday requires13, Wednesday requires 15, Thursday requires 19, Friday requires 14, Saturday requires 16, Sunday requires 11.\"",
      "options": [
        "rows = days Mon..Sun in the stated order, columns = shift start days Mon..Sun",
        "rows = shift start days Mon..Sun, columns = requirement days Mon..Sun"
      ],
      "plausibility": [
        0.9,
        0.1
      ],
      "majority_option": "rows = days Mon..Sun in the stated order, columns = shift start days Mon..Sun"
    },
    {
      "decision": "cyclic_week_wrap",
      "evidence": "\"each full-time employee must work five consecutive days and then receive two days off\"",
      "options": [
        "week is cyclic: a block starting Saturday covers Sat,Sun,Mon,Tue,Wed",
        "week is linear: blocks cannot wrap past Sunday (only 3 valid start days)"
      ],
      "plausibility": [
        0.95,
        0.05
      ],
      "majority_option": "week is cyclic: a block starting Saturday covers Sat,Sun,Mon,Tue,Wed"
    }
  ]
}
